from dataclasses import dataclass
from datetime import datetime, timedelta

BUSINESS_HOURS = range(9, 18)


@dataclass(frozen=True)
class SlaPolicy:
    first_response: timedelta
    resolution: timedelta


POLICIES = {
    "urgent": SlaPolicy(timedelta(hours=1), timedelta(hours=8)),
    "normal": SlaPolicy(timedelta(hours=8), timedelta(days=3)),
    "low": SlaPolicy(timedelta(days=1), timedelta(days=7)),
}


def first_response_due(created_at: datetime, priority: str) -> datetime:
    policy = POLICIES.get(priority, POLICIES["normal"])
    return created_at + policy.first_response

